<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:600px"><h5 class="mb-3">Edit Attendance</h5><form method="POST"><input type="hidden" name="id" value="<?=e($id)?>"><label class="form-label">Date</label><input type="date" name="date" class="form-control mb-3" value="<?=e($entry['date']??date('Y-m-d'))?>"><label class="form-label">Status</label><select name="status" class="form-select"><option value="present">Present</option><option value="absent">Absent</option><option value="late">Late</option><option value="excused">Excused</option></select><div class="mt-4"><button class="btn btn-primary">Save</button> <a class="btn btn-outline-secondary" href="<?=url('views/admin/attendance/view.php?id='.urlencode($id))?>">Cancel</a></div></form></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>